<?php
namespace App\Http\Controllers;use App\Contracts\DomainInspectorInterface;use App\Http\Requests\ExtractRequest;use App\Services\CsvService;use Illuminate\Http\JsonResponse;
final readonly class ExtractController {public function __construct(private CsvService $csv,private DomainInspectorInterface $domains){}public function __invoke(ExtractRequest $request):JsonResponse{$d=$request->validated();$providers=$d['providers']??['gmail','google_workspace','microsoft_365'];$custom=array_map('strtolower',$d['custom_domains']??[]);$out=[];foreach($request->file('files')as$file)foreach($this->csv->rows($file)as$row)foreach($row as$value){if(!is_string($value))continue;preg_match_all('/[A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,}/i',$value,$m);foreach($m[0]as$email){$host=strtolower(explode('@',$email,2)[1]);$provider=$host==='gmail.com'?'gmail':match($this->domains->mxProvider($host)){'Google Workspace'=>'google_workspace','Microsoft 365'=>'microsoft_365',default=>(in_array($host,$custom,true)?'custom':'other')};if(in_array($provider,$providers,true))$out[$email]=$provider;}}return response()->json(['ok'=>true,'data'=>['emails'=>array_map(fn(string $e,string $p):array=>['email'=>$e,'provider'=>$p],array_keys($out),$out),'count'=>count($out)]]);}}
